import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val str = reader.readLine() ?: return
    solution(str)
}

fun solution(str: String) {
    var count = 0
    var i: Int
    var j: Int
    for (index in str.indices) {
        i = index
        j = i - 1
        while (j >= 0) {
            if (str[i] == str[j]) {
                break
            }
            j--
        }
        if (j == -1) count++
    }
    if (count % 2 == 1) {
        println("IGNORE HIM!")
        return
    }
    println("CHAT WITH HER!")
    return
}

